// Decide, para cada producto de Lococo, si hay que CREARLO o ACTUALIZARLO en tu tienda,
// y qué productos tuyos ya no están en la lista (DESACTIVAR). El emparejamiento es por modelo.
const scr = $('Scrapear Lococo').first().json;
const raw = $('Mis productos').all().map(i => i.json);
const mine = (raw.length === 1 && Array.isArray(raw[0].products) ? raw[0].products : raw).filter(p => p && p.id);
const bool = (v, d) => v === undefined || v === '' ? d : String(v).toLowerCase() === 'true';
const DEACT = bool($env.DEACTIVATE_MISSING, true);
const MIN_SCRAPE = Number($env.MIN_SCRAPE_COUNT || 800);
const MAX_DET = Number($env.DETAILS_MAX_PER_RUN || 300);
const K = s => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '');

const items = scr.items || [];
if (items.length < MIN_SCRAPE) {
  throw new Error(`Lococo devolvió ${items.length} productos (mínimo esperado ${MIN_SCRAPE}). Freno para no desactivar tu catálogo por un scraping roto.`);
}

const byKey = new Map();
for (const p of mine) { const k = K(p.model); if (k) { if (!byKey.has(k)) byKey.set(k, []); byKey.get(k).push(p); } }

const plan = [];
const used = new Set();
const pending = [];
const bySrc = new Map();
for (const p of mine) if (p.sourceId) { if (!bySrc.has(p.sourceId)) bySrc.set(p.sourceId, []); bySrc.get(p.sourceId).push(p); }
// 1) ID de Lococo (prod_…) y, si no, modelo exacto (sin importar guiones, espacios ni mayúsculas)
for (const s of items) {
  const byId = s.prod_id ? (bySrc.get(s.prod_id) || []).filter(p => !used.has(p.id)) : [];
  if (byId.length) { byId.forEach(p => used.add(p.id)); plan.push({ op: 'update', s, products: byId, match_type: 'id' }); continue; }
  const hits = (byKey.get(K(s.code)) || []).filter(p => !used.has(p.id));
  if (hits.length) { hits.forEach(p => used.add(p.id)); plan.push({ op: 'update', s, products: hits, match_type: 'exacto' }); }
  else pending.push(s);
}
// 2) Un modelo contiene al otro (ej. HAC-B1A21P dentro de DH-HAC-B1A21P-U-0280B), solo si hay un único candidato libre
for (const s of pending) {
  const k = K(s.code);
  const cands = k.length >= 6 && s.model_source !== 'generado'
    ? mine.filter(p => !used.has(p.id) && K(p.model).length >= 6 && (K(p.model).includes(k) || k.includes(K(p.model))))
    : [];
  if (cands.length === 1) { used.add(cands[0].id); plan.push({ op: 'update', s, products: cands, match_type: 'contiene' }); }
  else plan.push({ op: 'create', s, products: [], match_type: 'nuevo' });
}
// 3) Productos tuyos que ya no están en Lococo
const missing = mine.filter(p => !used.has(p.id) && K(p.model));
if (DEACT) for (const p of missing) if (p.active !== false) plan.push({ op: 'deactivate', s: null, products: [p], match_type: 'no está en Lococo' });

// Fichas a bajar: primero los nuevos, después los que tienen la ficha incompleta
const needs = [];
for (const e of plan.filter(e => e.op === 'create')) needs.push(e.s.search);
for (const e of plan.filter(e => e.op === 'update'))
  if (e.products.some(p => !(p.specs && p.specs.length) || !p.category || (!p.sourceId && !e.s.prod_id))) needs.push(e.s.search);
const need_details = [...new Set(needs)].slice(0, MAX_DET);

return [{ json: {
  plan, need_details,
  stats: {
    lococo: items.length, mios: mine.length,
    crear: plan.filter(e => e.op === 'create').length,
    actualizar: plan.filter(e => e.op === 'update').length,
    match_por_id: plan.filter(e => e.match_type === 'id').length,
    desactivar: plan.filter(e => e.op === 'deactivate').length,
    duplicados: plan.filter(e => e.products.length > 1).map(e => ({ modelo: e.s.code, productos: e.products.map(p => p.sku || p.id) })),
    sin_modelo_en_tu_tienda: mine.filter(p => !K(p.model)).length,
    fichas_pedidas: need_details.length, fichas_pendientes: Math.max(0, new Set(needs).size - need_details.length),
  },
} }];

// Arma las tandas del loop. Cada tanda = hasta DETAILS_CHUNK fichas + los productos que dependen de ellas.
// La tanda 1 además lleva todo lo que no necesita ficha (precio/stock de los que ya están completos, desactivar).
const { plan, need_details } = $input.first().json;
const size = Number($env.DETAILS_CHUNK || 40);
const tandas = [];
for (let i = 0; i < need_details.length; i += size) tandas.push({ codes: need_details.slice(i, i + size), entries: [] });
if (!tandas.length) tandas.push({ codes: [], entries: [] });
const where = new Map();
tandas.forEach((t, i) => t.codes.forEach(c => where.set(c, i)));
for (const e of plan) {
  const i = e.s ? where.get(e.s.search) : undefined;
  tandas[i === undefined ? 0 : i].entries.push(e);
}
// IDs de Lococo conocidos (de la lista o ya guardados en tu tienda): el scraper abre esas fichas directo
for (const t of tandas) {
  t.ids = {};
  for (const e of t.entries) {
    const pid = e.s && (e.s.prod_id || (e.products || []).map(p => p.sourceId).find(Boolean));
    if (pid && t.codes.includes(e.s.search)) t.ids[e.s.search] = pid;
  }
}
return tandas.map((t, i) => ({ json: { tanda: i + 1, de: tandas.length, ...t } }));

// Arma lo que se manda a tu tienda. Precio y stock se actualizan siempre;
// nombre, marca, categoría, ficha y foto solo se completan si están vacíos (salvo OVERWRITE_CONTENT=true).
// Solo procesa los productos de la TANDA actual del loop.
const { entries: plan, tanda, codes } = $('Recorrer tandas').first().json;
const fichas = $('Fichas Lococo').all().map(i => i.json || {});
const det = { items: fichas.flatMap(f => f.items || []), errors: fichas.flatMap(f => f.errors || []) };
// Si el scraper se cayó en esta tanda, sus fichas quedan como error (se reintentan la próxima corrida)
const caida = fichas.find(f => f.error || (f.detail && !f.items));
if (caida && codes.length) det.errors.push(...codes.filter(c => !det.items.some(d => d.code === c) && !det.errors.some(x => x.code === c))
  .map(c => ({ code: c, error: 'scraper caído en esta tanda: ' + String(caida.error?.message || caida.error || caida.detail).slice(0, 120) })));
const scr = $('Scrapear Lococo').first().json;
const bool = (v, d) => v === undefined || v === '' ? d : String(v).toLowerCase() === 'true';
const num = (v, d) => v === undefined || v === '' || isNaN(Number(v)) ? d : Number(v);

const TARGET = String($env.TARGET_CURRENCY || 'USD').toUpperCase();
const MARGIN = num($env.PRICE_MARGIN_PCT, 0);
const IVA = num($env.ADD_IVA_PCT, 0);
const ROUND = num($env.PRICE_ROUND_TO, 0.01);
const MAX_CHANGE = num($env.MAX_CHANGE_PCT, 30);
const RATE = num($env.USD_RATE, 0) || scr.usd_rate || 0;
const OVERWRITE = bool($env.OVERWRITE_CONTENT, false);
const PUBLISH_NEW = bool($env.PUBLISH_NEW, true);
const ONLY_WITH_DETAILS = bool($env.CREATE_ONLY_WITH_DETAILS, true);
const IN_STOCK = String($env.IN_STOCK_STATUSES || 'inmediato,deposito_2,tercer_deposito').split(',').map(s => s.trim());
const TITLE = String($env.NAME_STYLE || 'title').toLowerCase() === 'title';
const SEND_SRC = bool($env.SEND_SOURCE_FIELDS, true);  // sourceId + sourceUrl (Projaska ya tiene los campos)
const PLACEHOLDER = /catalog-fallbacks|category-pending/;

const details = new Map((det.items || []).map(d => [d.code, d]));
const round2 = n => Math.round(n * 100) / 100;

function price(s) {
  let p = s.price;
  const cur = String(s.currency || 'USD').toUpperCase();
  if (cur !== TARGET) {
    if (!RATE) return null;
    p = cur === 'USD' ? p * RATE : p / RATE;
  }
  p = p * (1 + IVA / 100) * (1 + MARGIN / 100);
  return ROUND > 1 ? Math.round(p / ROUND) * ROUND : round2(p);
}

const ACR = new Set(['IP','PTZ','DVR','NVR','XVR','HD','UTP','FTP','POE','HDMI','VGA','USB','LED','IR','RFID','AHD','TVI','CVI','HDCVI','WDR','ONVIF','SD','PIR','GSM','LTE','4G','UPS','RJ45','CAT','DC','AC','PVC','OEM','2K','4K','DVR/NVR','NFC','SIM','LAN','WAN','SSD','HDD','MP','MM','TB','GB','MB','MBPS','GBPS','MHZ','GHZ','W','V','VA','AH','KVA','M','U','CM','FPS','DB','IP65','IP66','IP67']);
const LOW = new Set(['DE','DEL','CON','Y','A','PARA','EN','SIN','O','LA','EL','LOS','LAS','POR','X']);
function nice(name) {
  if (!TITLE) return name;
  return name.split(' ').map((w, i) => w.split('-').map(p => {
    const U = p.toUpperCase();
    if (!p || /\d/.test(p) || ACR.has(U) || /^[^A-ZÁÉÍÓÚÑ]+$/i.test(p)) return U;
    if (i > 0 && LOW.has(U)) return p.toLowerCase();
    return p.charAt(0).toUpperCase() + p.slice(1).toLowerCase();
  }).join('-')).join(' ').replace(/\s·\s/g, ' · ');
}
// La ficha técnica va en `specs` (la tienda la muestra aparte); la descripción es solo el nombre.
const descOf = name => `${name}.`;
const SPECS_EN_DESC = '\n\nCaracterísticas:';
const empty = v => v === null || v === undefined || v === '' || (Array.isArray(v) && !v.length);

const out = [];
const postergados = [];
for (const e of plan) {
  if (e.op === 'deactivate') {
    const p = e.products[0];
    out.push({ json: { op: 'deactivate', match: { id: p.id }, data: { active: false, inStock: false }, label: p.sku || p.model, motivo: e.match_type } });
    continue;
  }
  const s = e.s;
  const d = details.get(s.search);
  const specs = d?.specs || [];
  const category = d?.category || null;
  const imageUrl = [s.image_url, d?.image_url].find(u => u && !PLACEHOLDER.test(u)) || null;  // la de la lista es la misma foto y es confiable
  const sourceUrl = d?.source_url || s.source_url || null;
  const sourceId = s.prod_id || d?.prod_id || null;
  const name = nice(s.raw_name);
  const newPrice = price(s);
  const stockStatus = s.stock_status;
  const inStock = IN_STOCK.includes(stockStatus);

  if (e.op === 'create') {
    if (newPrice === null) { postergados.push({ modelo: s.code, motivo: 'sin cotización para convertir moneda' }); continue; }
    if (!d && ONLY_WITH_DETAILS) { postergados.push({ modelo: s.code, motivo: 'ficha pendiente (se crea en la próxima corrida)' }); continue; }
    out.push({ json: { op: 'create', match: null, label: s.code, motivo: 'nuevo en Lococo', data: {
      model: s.code, sku: s.code, name, description: descOf(name), brand: s.brand, category,
      price: newPrice, stockStatus, inStock, active: PUBLISH_NEW, specs, imageUrl,
      ...(SEND_SRC && sourceId ? { sourceId } : {}), ...(SEND_SRC && sourceUrl ? { sourceUrl } : {}),
    } } });
    continue;
  }

  // update: puede haber más de un producto tuyo con el mismo modelo (duplicados) -> se actualizan todos
  for (const p of e.products) {
    const data = {};
    let review = null;
    if (newPrice !== null && newPrice !== Number(p.price)) {
      const pct = Number(p.price) > 0 ? Math.abs(newPrice - p.price) / p.price * 100 : 0;
      if (pct > MAX_CHANGE) review = `precio ${p.price} -> ${newPrice} (${pct.toFixed(0)}%)`;
      else data.price = newPrice;
    }
    if (p.stockStatus !== stockStatus) data.stockStatus = stockStatus;
    if (p.inStock !== inStock) data.inStock = inStock;
    if (p.active === false) data.active = true;  // volvió a la lista de Lococo
    // Matcheado por ID pero Lococo cambió el modelo: se corrige (y el SKU, si era igual al modelo)
    const KK = v => String(v || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
    if (e.match_type === 'id' && s.model_source !== 'generado' && KK(p.model) !== KK(s.code)) {
      data.model = s.code;
      if (KK(p.sku) === KK(p.model)) data.sku = s.code;
    }
    const fill = (k, v) => { if (!empty(v) && (OVERWRITE ? JSON.stringify(p[k]) !== JSON.stringify(v) : empty(p[k]))) data[k] = v; };
    fill('brand', s.brand);
    fill('category', category);
    fill('specs', specs);
    // Si se guardó el placeholder de Lococo ("sin foto") como imagen, se reemplaza
    if (PLACEHOLDER.test(String(p.sourceImageUrl || '') + String(p.imageUrl || ''))) data.imageUrl = imageUrl;
    else fill('imageUrl', imageUrl);
    // El ID/link de Lococo se corrige si cambió (ej. prod_catalog_… que se regeneró)
    if (SEND_SRC && sourceId && p.sourceId !== sourceId && !e.products.some(o => o !== p && o.sourceId === sourceId)) data.sourceId = sourceId;
    if (SEND_SRC && sourceUrl && p.sourceUrl !== sourceUrl) data.sourceUrl = sourceUrl;
    // Limpia descripciones viejas que traían la ficha copiada adentro
    if (typeof p.description === 'string' && p.description.includes(SPECS_EN_DESC)) data.description = p.description.split(SPECS_EN_DESC)[0];
    else fill('description', descOf(OVERWRITE ? name : (p.name || name)));
    if (OVERWRITE) fill('name', name);
    if (!Object.keys(data).length && !review) continue;  // sin cambios
    out.push({ json: { op: 'update', match: { id: p.id }, data, label: p.sku || s.code, motivo: e.match_type,
                       review, duplicado: e.products.length > 1 } });
  }
}
// Un item extra con el resumen del plan (no se manda a la tienda)
out.push({ json: { op: 'resumen', tanda, postergados, fichas_con_error: det.errors || [] } });
return out;

// Agrupa las operaciones de ESTA tanda de a BATCH_SIZE. Siempre devuelve algo para que el loop siga.
const ops = $input.all().map(i => i.json).filter(o => o.op !== 'resumen' && Object.keys(o.data || {}).length);
const dry = String($env.DRY_RUN).toLowerCase() !== 'false';
if (dry || !ops.length) return [{ json: { send: false, motivo: dry ? 'DRY_RUN' : 'sin cambios', ops: ops.length } }];
const size = Number($env.BATCH_SIZE || 50);
const out = [];
for (let i = 0; i < ops.length; i += size) out.push({ json: { send: true,
  items: ops.slice(i, i + size).map(({ op, match, data }) => ({ op, match, data })),
  labels: ops.slice(i, i + size).map(o => o.label) } });
return out;

// Resumen de ESTA tanda (vuelve al loop y se junta al final)
const t = $('Recorrer tandas').first().json;
const ops = $('Armar operaciones').all().map(i => i.json);
const head = ops.find(o => o.op === 'resumen') || {};
const lotes = $('Agrupar en lotes').all().map(i => i.json);
const enviado = $input.first().json.send !== false;
const tally = {}; const errores = []; const avisos = [];
if (enviado) $input.all().forEach((it, i) => {
  const sc = it.json.statusCode;
  const labels = lotes[i]?.labels || [];
  if (sc !== 200) { errores.push({ tanda: t.tanda, lote: i + 1, status: sc ?? null, error: it.json.body?.error ?? it.json.body ?? it.json.error ?? null }); return; }
  (it.json.body?.results || []).forEach((r, j) => {
    tally[r.status] = (tally[r.status] || 0) + 1;
    const prod = labels[j] ?? r.model ?? r.id;
    if (r.status === 'error') errores.push({ producto: prod, error: r.error });
    if (r.warning) avisos.push({ producto: prod, aviso: r.warning });
  });
});
// Si NADA de la tanda se pudo guardar, se frena todo: seguro es un problema de configuración (key, campos, endpoint)
const total = Object.values(tally).reduce((a, b) => a + b, 0);
if (enviado && errores.length && (tally.error || 0) + errores.filter(e => e.status !== undefined).length >= Math.max(1, total)) {
  const ej = errores[0];
  throw new Error(`Tanda ${t.tanda}: tu tienda rechazó TODO (${errores.length} errores). Freno el flujo. Ejemplo: ${ej.producto ?? 'lote ' + ej.lote} → ${String(ej.error?.message ?? ej.error ?? ej.status).slice(0, 200)}`);
}
return [{ json: {
  tanda: t.tanda, de: t.de, enviado, motivo: enviado ? null : $input.first().json.motivo,
  operaciones: ops.filter(o => o.op !== 'resumen').length,
  resultado: tally, errores, avisos,
  revisar_a_mano: ops.filter(o => o.review).map(o => ({ producto: o.label, motivo: o.review })),
  postergados: head.postergados || [], fichas_con_error: head.fichas_con_error || [],
} }];

// Junta los resúmenes de todas las tandas
const tandas = $input.all().map(i => i.json).filter(t => t.tanda);
const plan = $('Planificar').first().json.stats;
const tally = {};
tandas.forEach(t => Object.entries(t.resultado || {}).forEach(([k, v]) => tally[k] = (tally[k] || 0) + v));
const all = k => tandas.flatMap(t => t[k] || []);
return [{ json: {
  tandas: tandas.length,
  resultado: tally,
  no_enviadas: tandas.filter(t => !t.enviado).map(t => ({ tanda: t.tanda, motivo: t.motivo, operaciones: t.operaciones })),
  errores: all('errores'),
  avisos: all('avisos'),
  revisar_a_mano: all('revisar_a_mano'),
  duplicados_en_tu_tienda: plan.duplicados || [],
  postergados: { total: all('postergados').length, ejemplos: all('postergados').slice(0, 20) },
  fichas_con_error: all('fichas_con_error'),
  plan,
} }];

// Arma el mensaje de Telegram (texto plano, máx. 4096 caracteres)
const r = $input.first().json;
const t = r.resultado || {};
const p = r.plan || {};
const L = [];
const lista = (titulo, arr, fmt, max = 15) => {
  if (!arr.length) return;
  L.push('', `${titulo} (${arr.length}):`);
  arr.slice(0, max).forEach(x => L.push('• ' + fmt(x)));
  if (arr.length > max) L.push(`  …y ${arr.length - max} más`);
};
const dry = String($env.DRY_RUN).toLowerCase() !== 'false';
const ahora = new Date().toLocaleString('es-AR', { timeZone: 'America/Argentina/Mendoza', hour12: false });

L.push(`📦 Catálogo Lococo → Projaska${dry ? ' (DRY RUN, no se guardó nada)' : ''}`, ahora, '');
L.push(`✅ Creados: ${t.created || 0}`);
L.push(`🔄 Actualizados: ${t.updated || 0}`);
L.push(`⏸ Desactivados: ${t.deactivated || 0}`);
if (t.unchanged) L.push(`➖ Sin cambios: ${t.unchanged}`);
const porId = p.match_por_id; if (porId !== undefined) L.push(`🔗 Matcheados por ID Lococo: ${porId}`);
L.push(`Lococo: ${p.lococo ?? '?'} productos · tu tienda: ${p.mios ?? '?'}`);

const sinCargar = (r.errores || []).length + (r.fichas_con_error || []).length;
L.push('', sinCargar ? `❌ No se pudieron cargar: ${sinCargar}` : '👌 Sin errores');
lista('Errores al guardar', r.errores || [], x => `${x.producto ?? ('tanda ' + x.tanda + ' lote ' + x.lote)}: ${String(x.error?.message ?? x.error ?? x.status).slice(0, 80)}`);
lista('Fichas que fallaron', r.fichas_con_error || [], x => `${String(x.code).slice(0, 50)}: ${String(x.error).slice(0, 60)}`);
if (r.postergados?.total) L.push('', `⏳ Quedan para la próxima corrida: ${r.postergados.total} (sin ficha todavía)`);
const fotos = (r.avisos || []).filter(a => /resoluci/i.test(a.aviso));
lista('📷 Fotos de baja resolución', fotos, x => `${x.producto}: ${String(x.aviso).replace(/^foto de baja resolución\s*/i, '')}`, 10);
lista('Otros avisos', (r.avisos || []).filter(a => !/resoluci/i.test(a.aviso)), x => `${x.producto}: ${String(x.aviso).slice(0, 80)}`, 10);
lista('Revisar a mano (cambio de precio grande)', r.revisar_a_mano || [], x => `${x.producto}: ${x.motivo}`, 10);
lista('Tandas no enviadas', (r.no_enviadas || []).filter(x => x.motivo !== 'sin cambios'), x => `tanda ${x.tanda}: ${x.motivo}`, 5);
if ((r.duplicados_en_tu_tienda || []).length) L.push('', `⚠️ Modelos duplicados en tu tienda: ${r.duplicados_en_tu_tienda.length}`);

let text = L.join('\n');
if (text.length > 4000) text = text.slice(0, 3990) + '\n…(cortado)';
return [{ json: { text } }];
